import {pickCaption,validOuting,nextVisit} from './outing-core.mjs';
const $=s=>document.querySelector(s);
const KEY='hope-outing-v1';
function read(){try{return JSON.parse(localStorage.getItem(KEY));}catch{return null;}}
let state=read(),photo=null,parkingPhoto=null,cardBlob=null,cardUrl=null,processing=false;
if(!validOuting(state))state=null;
let context={club:'—',course:'links',hole:1};
const db=new Promise((resolve,reject)=>{const r=indexedDB.open('hope-outing-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('media');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
db.catch(()=>{});
async function media(action,key,value){const d=await db;return new Promise((resolve,reject)=>{const t=d.transaction('media',action==='get'?'readonly':'readwrite'),s=t.objectStore('media'),r=action==='get'?s.get(key):action==='put'?s.put(value,key):action==='delete'?s.delete(key):s.clear();let result;r.onsuccess=()=>{result=r.result;};t.oncomplete=()=>resolve(result);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{return false;}}
function show(id){for(const s of ['#parking-screen','#welcome','#tee-ready','main','#finish-screen'])$(s).hidden=s!==id;}
function localDate(){return new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(state?.createdAt||Date.now()));}
async function fresh(){state={id:crypto.randomUUID(),createdAt:Date.now(),completed:0,reminded:false,parking:null,phase:'parking',caption:pickCaption()};photo=parkingPhoto=cardBlob=null;context.club='—';for(const id of ['#finish-parking','#finish-leave'])$(id).hidden=false;save();await media('clear').catch(()=>{});updatePhotoButtons();$('#parking-note').textContent='좌표나 사진, 편한 쪽 하나만.';$('#parking-skip').textContent='건너뛰고 시작';}
function updatePhotoButtons(){for(const b of document.querySelectorAll('[data-photo-open]'))b.textContent=photo?'오늘의 사진 · 카드 공유 ↗':b.closest?.('.photo-invite')?'티샷 전에 한 컷 ↗':'시작 전에 한 컷 ↗';$('#finish-card').hidden=!photo;$('#finish-photo').hidden=!!photo;$('#photo-card-actions').hidden=!photo;$('#photo-preview').hidden=!photo;$('.photo-pickers').hidden=!!photo;$('#photo-done').textContent=photo?'좋아, 계속하자 →':'사진 없이 계속하기 →';}
async function resize(file,max=1600){if(file.size>30*1024*1024)throw Error('30MB 이하 사진을 선택해주세요.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const ratio=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(image.naturalWidth*ratio);c.height=Math.round(image.naturalHeight*ratio);c.getContext('2d').drawImage(image,0,0,c.width,c.height);return await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('사진 변환에 실패했습니다.')),'image/jpeg',.86));}catch(e){throw Error(e.message==='30MB 이하 사진을 선택해주세요.'?e.message:'사진을 열지 못했습니다. JPG 또는 PNG 사진으로 다시 선택해주세요.');}finally{URL.revokeObjectURL(url);}}
async function drawCard(){if(!photo)return;$('#share-card').disabled=true;$('#download-card').hidden=true;const url=URL.createObjectURL(photo);try{const image=new Image();image.src=url;await image.decode();const c=$('#photo-canvas'),x=c.getContext('2d');const photoH=Math.max(540,Math.min(1250,Math.round(1080*image.height/image.width)));c.width=1080;c.height=photoH+340;x.fillStyle='#bee0a1';x.fillRect(0,0,1080,c.height);const scale=Math.min(1080/image.width,photoH/image.height),w=image.width*scale,h=image.height*scale;x.drawImage(image,(1080-w)/2,(photoH-h)/2,w,h);x.fillStyle='#20613e';x.fillRect(0,photoH,1080,340);x.fillStyle='#fff6e4';x.font='800 76px -apple-system, sans-serif';x.shadowColor='#0006';x.shadowBlur=10;x.fillText('hope.',55,105);x.shadowBlur=0;x.font='600 31px -apple-system, sans-serif';x.fillStyle='#c4dda9';x.fillText(`${localDate()}  ·  ${context.club}`,55,photoH+65);x.font='800 62px -apple-system, sans-serif';x.fillStyle='#fff6e4';let lines=[''];for(const char of state.caption){const i=lines.length-1;if(x.measureText(lines[i]+char).width>970)lines.push(char);else lines[i]+=char;}lines.slice(0,3).forEach((line,i)=>x.fillText(line,55,photoH+160+i*75));cardBlob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!cardBlob)throw Error('카드를 만들지 못했습니다.');if(cardUrl)URL.revokeObjectURL(cardUrl);cardUrl=URL.createObjectURL(cardBlob);const download=$('#download-card');download.href=cardUrl;download.download='hope-'+new Date(state.createdAt).toISOString().slice(0,10)+'.png';download.hidden=false;$('#share-card').disabled=false;$('#photo-caption').textContent=state.caption;$('#photo-note').textContent='사진 전체를 담았습니다. 카드로 저장하거나 공유하세요.';}finally{URL.revokeObjectURL(url);}}
async function openPhoto(){if(processing)return;$('#photo-dialog').showModal();updatePhotoButtons();if(photo){try{await drawCard();}catch(e){$('#photo-note').textContent=e.message;}}else $('#photo-note').textContent='티샷 전에 한 장. 나중에 골라도 됩니다.';}
for(const b of document.querySelectorAll('[data-photo-open]'))b.onclick=openPhoto;
$('#photo-close').onclick=()=>$('#photo-dialog').close();$('#photo-done').onclick=()=>$('#photo-dialog').close();
$('#photo-camera').onclick=()=>$('#round-camera').click();$('#photo-library').onclick=()=>$('#round-library').click();
for(const id of ['#round-camera','#round-library'])$(id).onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||processing)return;processing=true;$('#photo-note').textContent='사진 준비 중…';try{const blob=await resize(file);photo=blob;state.caption=pickCaption(state.caption);save();let persisted=true;try{await media('put','round',{id:state.id,blob});}catch{persisted=false;}updatePhotoButtons();await drawCard();if(!persisted)$('#photo-note').textContent='이 기기에 사진을 보관하지 못했습니다. 지금 카드를 저장하거나 공유해주세요.';}catch(err){$('#photo-note').textContent=err.message;}finally{processing=false;}};
$('#caption-again').onclick=async()=>{if(!photo||processing)return;state.caption=pickCaption(state.caption);save();await drawCard().catch(e=>$('#photo-note').textContent=e.message);};
$('#share-card').onclick=async()=>{if(!cardBlob)return;const file=new File([cardBlob],'hope-round.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'오늘의 한 컷 · hope.'});}catch(e){if(e.name!=='AbortError')$('#photo-note').textContent='공유하지 못했습니다. 카드 저장을 이용해주세요.';}}else $('#photo-note').textContent='이 브라우저에서는 카드 저장 후 사진 앱에서 공유해주세요.';};
$('#parking-save').onclick=async()=>{if(processing)return;processing=true;$('#parking-save').disabled=true;$('#parking-note').textContent='주차한 위치 확인 중…';try{const pos=await new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('위치를 지원하지 않습니다.'));navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,maximumAge:0,timeout:15000});});if(pos.coords.accuracy>100)throw Error('위치 오차가 큽니다. 구역 사진을 남겨주세요.');state.parking={lat:pos.coords.latitude,lon:pos.coords.longitude,accuracy:pos.coords.accuracy};const saved=save();$('#parking-note').textContent=`현재 주차 위치 저장 · GPS 오차 약 ${Math.round(pos.coords.accuracy)}m`+(saved?'':' · 기기 보관 실패, 앱을 닫으면 사라질 수 있습니다.');$('#parking-skip').textContent='좋아, 시작하자 ↗';}catch(e){$('#parking-note').textContent=e.code===1?'위치 권한이 없어도 구역 사진을 남기거나 건너뛸 수 있습니다.':e.message||'위치 확인 실패. 사진을 남기거나 건너뛰어도 됩니다.';}finally{processing=false;$('#parking-save').disabled=false;}};
$('#parking-camera').onclick=()=>$('#parking-file').click();$('#parking-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||processing)return;processing=true;try{parkingPhoto=await resize(file,1200);await media('put','parking',{id:state.id,blob:parkingPhoto});$('#parking-note').textContent='주차 구역 사진 저장. 이제 가보자고.';$('#parking-skip').textContent='좋아, 시작하자 ↗';}catch(e){$('#parking-note').textContent='사진 보관 실패. 위치를 저장하거나 건너뛰어도 됩니다.';}finally{processing=false;}};
$('#parking-skip').onclick=()=>{if(processing)return;state.phase='setup';save();show('#welcome');};
async function openParking(){const d=$('#parking-dialog');$('#parking-clear').hidden=!(state?.parking||parkingPhoto);$('#parking-detail').textContent=state?.parking?`저장한 주차 위치 · 오차 약 ${Math.round(state.parking.accuracy)}m`:'저장한 주차 좌표가 없습니다.';$('#parking-map').hidden=!state?.parking;if(state?.parking)$('#parking-map').href=`https://map.kakao.com/link/map/${encodeURIComponent('내 차 여기.')},${state.parking.lat},${state.parking.lon}`;const img=$('#parking-image');img.hidden=!parkingPhoto;if(parkingPhoto){if(img.dataset.url)URL.revokeObjectURL(img.dataset.url);img.src=URL.createObjectURL(parkingPhoto);img.dataset.url=img.src;}d.showModal();}
$('#finish-parking').onclick=openParking;$('#parking-close').onclick=()=>$('#parking-dialog').close();$('#parking-clear').onclick=async()=>{state.parking=null;parkingPhoto=null;save();await media('delete','parking').catch(()=>{});$('#parking-dialog').close();$('#finish-message').textContent='차도 찾았고, 이제 집으로. 주차 정보는 비웠습니다.';};
$('#reminder-photo').onclick=()=>{$('#photo-reminder').hidden=true;openPhoto();};$('#reminder-dismiss').onclick=()=>$('#photo-reminder').hidden=true;
function finish(){state.phase='finished';save();try{localStorage.removeItem('hope-live-round');}catch{}$('#finish-club').textContent=context.club+' · '+localDate();updatePhotoButtons();$('#photo-reminder').hidden=true;show('#finish-screen');document.dispatchEvent(new CustomEvent('hope:finished'));}
for(const b of document.querySelectorAll('[data-finish]'))b.onclick=()=>{if(context.isBusy?.())return;$('#next-course-label').hidden=true;$('#next-dialog h3').textContent='오늘은 여기까지';$('#next-question').textContent='오늘 라운드를 마칠까요?';$('#next-confirm').textContent='마치기';$('#next-dialog').dataset.finish='1';$('#next-dialog').showModal();};
$('#finish-card').onclick=openPhoto;$('#finish-photo').onclick=openPhoto;
$('#finish-leave').onclick=async()=>{if(processing)return;processing=true;try{for(const key of [KEY,'hope-live-round','hope-course'])localStorage.removeItem(key);await media('clear').catch(()=>{});photo=parkingPhoto=cardBlob=null;if(cardUrl)URL.revokeObjectURL(cardUrl);cardUrl=null;const img=$('#parking-image');if(img.dataset.url)URL.revokeObjectURL(img.dataset.url);img.src='';delete img.dataset.url;$('#parking-map').href='';$('#download-card').href='';$('#download-card').hidden=true;const canvas=$('#photo-canvas');canvas.width=canvas.height=0;state=null;context.club='—';updatePhotoButtons();for(const id of ['#finish-card','#finish-photo','#finish-parking','#finish-leave'])$(id).hidden=true;$('#finish-club').textContent='hope.';$('#finish-message').textContent='오늘 자료는 비웠습니다. 좋은 귀가 되세요.';document.dispatchEvent(new CustomEvent('hope:finished'));}finally{processing=false;}};
$('#new-outing').onclick=async()=>{if(processing)return;await fresh();document.dispatchEvent(new CustomEvent('hope:new-outing'));show('#parking-screen');};
export const outing={
 clearClub(){delete state.club;state.phase='setup';state.completed=0;state.reminded=false;context.club='—';save();},
 selectClub(club){state.club=club;context.club=club;save();},
 selectedClub(){return state?.club||'';},
 setContext(value){context={...context,...value};},
 offerPhoto(){if(!photo&&!state.photoOffered){state.photoOffered=true;save();openPhoto();}},
 start(){if(state){state.phase='playing';state.club=context.club;save();}},
 next(){const n=nextVisit(state?.completed||0);return n;},
 advance(){const n=nextVisit(state.completed);state.completed=n.completed;save();if(n.remind&&!state.reminded){state.reminded=true;save();$('#photo-reminder').hidden=false;}return n;},
 finish,
 async init(hasLiveRound){if(!state)await fresh();else{const data=await Promise.allSettled([media('get','round'),media('get','parking')]);photo=data[0].status==='fulfilled'&&data[0].value?.id===state.id?data[0].value.blob:null;parkingPhoto=data[1].status==='fulfilled'&&data[1].value?.id===state.id?data[1].value.blob:null;context.club=state.club||context.club;updatePhotoButtons();}if(hasLiveRound){state.phase='playing';save();return;}if(state.phase==='finished')finish();else if(state.phase==='parking')show('#parking-screen');else show('#welcome');}
};
